    "features.title": {"translations":{"landing":{"fr":"Tout ce qu'il vous faut pour r\u00e9ussir"}}},
    "features.item1.title": {"translations":{"landing":{"fr":"Libert\u00e9 de stockage"}}},
    "features.item1.subtitle": {"translations":{"landing":{"fr":"\"Bring Your Own Storage\""}}},
    "features.item1.desc": {"translations":{"landing":{"fr":"Ne soyez plus prisonnier. Connectez votre compte Google pour garder le contr\u00f4le total sur vos fichiers et votre calendrier."}}},
    "features.item2.title": {"translations":{"landing":{"fr":"Rangement par \"Organes\""}}},
    "features.item2.desc": {"translations":{"landing":{"fr":"Fini les listes de t\u00e2ches interminables. Regroupez vos actions dans des sous-projets clairs pour mieux respirer."}}},
    "features.item3.title": {"translations":{"landing":{"fr":"Ma\u00eetrisez l'urgence"}}},
    "features.item3.desc": {"translations":{"landing":{"fr":"Classez vos t\u00e2ches de 1 \u00e0 10 et liez-les \u00e0 des \u00e9ch\u00e9ances pr\u00e9cises. Filtrez instantan\u00e9ment pour voir ce qui doit \u00eatre fait maintenant."}}},
    "features.item4.title": {"translations":{"landing":{"fr":"R\u00f4les sur mesure"}}},
    "features.item4.desc": {"translations":{"landing":{"fr":"D\u00e9cidez exactement qui peut voir ou modifier quoi. Un contr\u00f4le total pour travailler en \u00e9quipe sans stress."}}},
    "collaboration.badge": {"translations":{"landing":{"fr":"Collaboration"}}},
    "collaboration.title": {"translations":{"landing":{"fr":"Travailler en essaim"}}},
    "collaboration.subtitle": {"translations":{"landing":{"fr":"Organ n'est pas qu'un gestionnaire de t\u00e2ches, c'est un syst\u00e8me nerveux pour votre \u00e9quipe. Travaillez ensemble avec une clart\u00e9 absolue sur les responsabilit\u00e9s de chacun."}}},
    "collaboration.item1.title": {"translations":{"landing":{"fr":"Tra\u00e7abilit\u00e9 Totale"}}},
    "collaboration.item1.desc": {"translations":{"landing":{"fr":"Chaque modification est enregistr\u00e9e. Qui a chang\u00e9 le statut ? Qui a d\u00e9cal\u00e9 l'\u00e9ch\u00e9ance ? Vous avez l'historique complet en un clic."}}},
    "collaboration.item2.title": {"translations":{"landing":{"fr":"D\u00e9pendances Intelligentes"}}},
    "collaboration.item2.desc": {"translations":{"landing":{"fr":"Visualisez ce qui bloque. Si la t\u00e2che B d\u00e9pend de la t\u00e2che A, Organ vous le montre clairement pour \u00e9viter les goulots d'\u00e9tranglement."}}},
    "collaboration.visual.lucas": {"translations":{"landing":{"fr":"<span class=\"text-bubblegum font-bold\">Lucas<\/span> a termin\u00e9 <span class=\"text-black italic\">\"Maquette Home\"<\/span>"}}},
    "collaboration.visual.sophie": {"translations":{"landing":{"fr":"<span class=\"text-highlight font-bold\">Sophie<\/span> peut d\u00e9buter <span class=\"text-black italic\">\"Int\u00e9gration CSS\"<\/span>"}}},
    "collaboration.visual.waiting": {"translations":{"landing":{"fr":"En attente de d\u00e9pendances..."}}},
    "collaboration.visual.visibility": {"translations":{"landing":{"fr":"100% de visibilit\u00e9"}}},
    "use_cases.badge": {"translations":{"landing":{"fr":"Exp\u00e9rience"}}},
    "use_cases.title": {"translations":{"landing":{"fr":"Concr\u00e8tement, comment \u00e7a se passe ?"}}},
    "use_cases.step1.title": {"translations":{"landing":{"fr":"Projet & \u00c9quipe"}}},
    "use_cases.step1.desc": {"translations":{"landing":{"fr":"Cr\u00e9ez votre projet et ajoutez vos collaborateurs en un clic via le menu ou par invitation directe par email."}}},
    "use_cases.step2.title": {"translations":{"landing":{"fr":"Invitations Fines"}}},
    "use_cases.step2.desc": {"translations":{"landing":{"fr":"Vous ne voulez pas tout montrer ? Invitez un client ou un freelance sur un <strong>organe<\/strong> sp\u00e9cifique uniquement. Rien d'autre ne sera visible pour lui."}}},
    "use_cases.step3.title": {"translations":{"landing":{"fr":"Contr\u00f4le Absolu"}}},
    "use_cases.step3.desc": {"translations":{"landing":{"fr":"Attribuez des r\u00f4les sur mesure : \"lecture seule\", \"cr\u00e9ateur de t\u00e2che\" ou \"valideur\". Chacun sait ce qu'il a \u00e0 faire, sans risque d'erreur."}}},
    "use_cases.quote": {"translations":{"landing":{"fr":"\"C'est cette gestion pr\u00e9cise qui nous permet de collaborer sur des projets complexes sans jamais nous marcher sur les pieds.\""}}},
    "about.badge": {"translations":{"landing":{"fr":"L'Origine du Projet"}}},
    "about.title": {"translations":{"landing":{"fr":"3 \u00e9tudiants, 3 visions, un seul outil"}}},
    "about.student1.role": {"translations":{"landing":{"fr":"Le Cr\u00e9atif"}}},
    "about.student1.quote": {"translations":{"landing":{"fr":"\"Besoin de visuel et de couleurs pour prioriser\""}}},
    "about.student2.role": {"translations":{"landing":{"fr":"Le Rigoureux"}}},
    "about.student2.quote": {"translations":{"landing":{"fr":"\"Tout doit \u00eatre hi\u00e9rarchis\u00e9 et rang\u00e9\""}}},
    "about.student3.role": {"translations":{"landing":{"fr":"L'Efficace"}}},
    "about.student3.quote": {"translations":{"landing":{"fr":"\"Je veux voir mes t\u00e2ches urgentes en 1 seconde\""}}},
    "about.origin.title": {"translations":{"landing":{"fr":"Le constat du chaos."}}},
    "about.origin.p1": {"translations":{"landing":{"fr":"Nous sommes 3 \u00e9tudiants en informatique. Chacun de nous a sa propre mani\u00e8re de s'organiser : certains jurent par des listes minimalistes, d'autres par des structures complexes."}}},
    "about.origin.p2": {"translations":{"landing":{"fr":"Pour travailler ensemble sur nos projets, rien n'\u00e9tait vraiment intuitif. Les outils existants nous obligeaient \u00e0 adopter une m\u00e9thode qui ne nous ressemblait pas. <strong>Organ est n\u00e9 pour fusionner nos besoins.<\/strong>"}}},
    "about.classic_tools.title": {"translations":{"landing":{"fr":"Le probl\u00e8me des outils classiques"}}},
    "about.classic_tools.subtitle": {"translations":{"landing":{"fr":"Pourquoi nous nous sentions toujours limit\u00e9s."}}},
    "about.classic_tools.item1.title": {"translations":{"landing":{"fr":"Le Mur de T\u00e2ches"}}},
    "about.classic_tools.item1.desc": {"translations":{"landing":{"fr":"Simple au d\u00e9but, mais se transforme vite en une liste infinie et angoissante."}}},
    "about.classic_tools.item2.title": {"translations":{"landing":{"fr":"Le Labyrinthe"}}},
    "about.classic_tools.item2.desc": {"translations":{"landing":{"fr":"Des pages dans des pages \u00e0 l'infini. On perd plus de temps \u00e0 ranger qu'\u00e0 faire."}}},
    "about.classic_tools.item3.title": {"translations":{"landing":{"fr":"La Hi\u00e9rarchie Organ"}}},
    "about.classic_tools.item3.quote": {"translations":{"landing":{"fr":"\"Projet > Organe > T\u00e2che.\""}}},
    "about.classic_tools.item3.desc": {"translations":{"landing":{"fr":"L'\u00e9quilibre parfait entre structure et libert\u00e9."}}},
    "about.philosophy.title": {"translations":{"landing":{"fr":"Reprenez le contr\u00f4le."}}},
    "about.philosophy.p1": {"translations":{"landing":{"fr":"Contrairement aux applications qui \"enferment\" vos donn\u00e9es pour vous forcer \u00e0 payer des abonnements de stockage, Organ utilise ce que vous avez d\u00e9j\u00e0."}}},
    "about.philosophy.p2": {"translations":{"landing":{"fr":"En connectant votre Google Drive, vous ne payez rien de plus et vos fichiers restent chez vous. C'est notre vision du <strong>\"Bring Your Own Storage\"<\/strong>."}}},
    "about.philosophy.visual.storage": {"translations":{"landing":{"fr":"Votre compte Google = Votre Stockage"}}},
